// report_table.cpp - formats a score report from "name score count" lines on stdin.
// Trap: exact printf formatting (%-10s, %8.3f, %e, %g, %+d, %x, %o, %%).
#include <cstdio>
#include <iostream>
#include <iomanip>
#include <string>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::string name;
    double score{};
    int count{};
    double total = 0.0;
    int sumc = 0;
    int n = 0;

    // Header
    std::printf("%-10s|%8s|%6s|%12s\n", "NAME", "SCORE", "COUNT", "SCI");

    while (true) {
        if (!(std::cin >> name >> score >> count))
            break;

        // Truncate name to 63 characters if necessary
        if (name.size() > 63)
            name.resize(63);

        // Data row
        std::printf("%-10.10s|%8.3f|%+6d|%12.4e\n",
                    name.c_str(), score, count, score);

        total += score;
        sumc += count;
        ++n;
    }

    if (n == 0) {
        std::printf("no rows\n");
        return 1;
    }

    std::printf("rows=%d avg=%g total=%.2f%% hex=%#x oct=%o\n",
                n, total / n, total, sumc, sumc);

    return 0;
}
